import sys

def solve():
    input_data = sys.stdin.read().split()
    if not input_data:
        return

    iterator = iter(input_data)
    try:
        t = int(next(iterator))
    except StopIteration:
        return

    results = []

    for _ in range(t):
        s = next(iterator)
        n = len(s)

        found = False
        ans = ""

        if s[0] != 'a':
            ans = 'a' + s
            found = True
        elif s[-1] != 'a':
            ans = s + 'a'
            found = True
        else:
            for i in range(n + 1):
                candidate = s[:i] + 'a' + s[i:]
                if candidate != candidate[::-1]:
                    ans = candidate
                    found = True
                    break

        if found:
            results.append("YES")
            results.append(ans)
        else:
            results.append("NO")

    print('\n'.join(results))

if __name__ == "__main__":
    solve()
